// Source of the machine-readable dictionaries for knowledge/language/{ru,en}-ai-markers.md.
// Every entry carries examples: yes = must match, no = must not match. build.mjs tests them and writes the JSON line.
const BL = String.raw`(?<![\p{L}\p{N}])`, BR = String.raw`(?![\p{L}\p{N}])`;
const sp = s => s.replace(/ /g, String.raw`\s+`);
const W = s => BL + '(?:' + sp(s) + ')' + BR;
// one word of a rhythm triad: adjective or adverb, not a colour, size, level, time of day or a noun in -ание/-ение/-тие
const TSTOP = String.raw`(?:\p{L}*(?:ани|ени|ти|ни)е(?![\p{L}])|(?:красн|син|зел[её]н|ж[её]лт|ч[её]рн|бел|сер|голуб|розов|оранжев|фиолетов|коричнев|бежев|начальн|базов|средн|продвинут|высш|перв|втор|трет|четв[её]рт|утренн|дневн|вечерн|ночн|маленьк|больш|крупн|мелк|сладк|сол[её]н|кисл|горьк|остр|летн|зимн|осенн|весенн|мужск|женск|детск|взросл)\p{L}*)`;
const TW = String.raw`(?!${TSTOP})\p{L}{4,}(?:о|ый|ий|ой|ая|яя|ое|ее|ые|ие)`;
// a hedge only as an introductory word: with a comma, or at the start of a sentence before a typical continuation
const HEDGE_INTRO = w => BL + String.raw`(?:(?:^\s*|(?<=[.!?…:;(«"]\s{0,3})|(?<=[,—–]\s{0,3}))(?:${w})(?=\s*,)|(?:^\s*|(?<=[.!?…]\s{1,3}))(?:${w})(?=\s+(?:вам|вы|вас|тебе|ты|мы|нам|это|стоит|лучше|подойд\p{L}*|понадоб\p{L}*|придётся|придется|получится)(?![\p{L}])))`;

const M = (id, level, category, pattern, hint, yes = [], no = [], flags = 'giu') => ({ id, pattern, flags, level, category, hint, _yes: yes, _no: no });
const E = (id, pattern, hint, yes = [], no = [], flags = 'giu') => ({ id, pattern, flags, ...(hint ? { hint } : {}), _yes: yes, _no: no });

